/**
 * A genuinely encrypted one-page PDF (RC4 128-bit, user password "test1234"),
 * produced by Ghostscript from a synthetic page. Unlike a trailer marker, its
 * object streams are encrypted, which is how real locked PDFs look.
 */
export const GHOSTSCRIPT_ENCRYPTED_PDF = Uint8Array.from(Buffer.from(
  "",
  "base64",
));
